<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\AboutPage;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\View\View;
class AboutPageController extends Controller {public function edit():View{return view('admin.about.edit',['settings'=>AboutPage::firstOrCreate([])]);}public function update(Request $r):RedirectResponse{$data=$r->validate(['about_page_title'=>['required','string','max:255'],'about_intro_label'=>['required','string','max:255'],'about_intro_content'=>['nullable','string'],'about_intro_video'=>['nullable','url','max:1000'],'about_director_title'=>['required','string','max:255'],'about_director_content'=>['nullable','string'],'about_director_name'=>['nullable','string','max:255'],'about_director_designation'=>['nullable','string','max:255'],'about_director_image'=>['nullable','image','max:10240'],'about_features_label'=>['required','string','max:255'],'about_features_title'=>['required','string','max:255'],'about_features_description'=>['nullable','string','max:2000'],'about_features_image'=>['nullable','image','max:10240'],'about_training_title'=>['required','string','max:255'],'about_training_video'=>['nullable','url','max:1000'],'about_training_background'=>['nullable','image','max:10240'],'about_certification_title'=>['required','string','max:255'],'about_faq_title'=>['required','string','max:255'],'about_faq_car_image'=>['nullable','image','max:10240'],'about_faq_bike_image'=>['nullable','image','max:10240']]);$s=AboutPage::firstOrCreate([]);foreach(['about_director_image','about_features_image','about_training_background','about_faq_car_image','about_faq_bike_image'] as $field){if($r->hasFile($field)){if($s->{$field})Storage::disk('public')->delete($s->{$field});$data[$field]=$r->file($field)->store('about','public');}else unset($data[$field]);}$s->update($data);return back()->with('status','About page updated successfully.');}}
